init:
try{sessionStorage.setItem('ft:intro-seen','1');sessionStorage.setItem('ft:debug-change','1')}catch(e){}
window.__errs=[];addEventListener('error',e=>__errs.push(String(e.message)));addEventListener('unhandledrejection',e=>__errs.push('rej '+String(e.reason)));
window.__sleep=ms=>new Promise(r=>setTimeout(r,ms));
window.__settle=async()=>{for(let i=0;i<300;i++){await __sleep(30);if(!document.documentElement.dataset.changeKind){await __sleep(300);return true}}return false};
window.__snap=tag=>{const h=document.documentElement,d=n=>h.style.getPropertyValue(n);return {tag,path:location.pathname,kind:h.dataset.changeKind||null,glass:h.dataset.glass||null,pushRadial:document.getElementById('ft-glass-ring-push').getAttribute('scale'),pushLinear:document.getElementById('ft-glass-strip-push').getAttribute('scale'),lineAnims:document.querySelector('[data-glass-line]').getAnimations().length,docAnims:document.getAnimations().length,marks:['--change-x','--change-y','--change-r','--change-w','--change-ms'].filter(n=>d(n)).length,errs:__errs.length}};
